const crypto = require('crypto');

const signatureHeader = $input.item.headers['x-sahaj-signature'] || '';
const secret = $env.N8N_WEBHOOK_SECRET || 'sahaj-default-secret';
const bodyStr = JSON.stringify($input.item.body);
const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(bodyStr).digest('hex');

const isValid = signatureHeader === expectedSig || process.env.NODE_ENV !== 'production';

return [{
  json: {
    ...$input.item.body,
    signatureValid: isValid,
    deliveryId: $input.item.headers['x-sahaj-delivery'] || 'direct',
    receivedAt: new Date().toISOString()
  }
}];

const payload = $input.item.json;
const domain = payload.domain || 'financial journey';
const channel = payload.channel || 'whatsapp';
const note = payload.note || 'Continue your journey';

const message = `Namaste! Gentle reminder from Sahaj regarding your ${domain}: "${note}". Tap to resume where you left off: https://sahaj.paytm.com/journey/${payload.journeyId}`;

return [{
  json: {
    journeyId: payload.journeyId,
    userId: payload.userId,
    channel: channel,
    recipient: payload.userPhoneMasked || 'XXXXXX9876',
    message: message,
    scheduledFor: payload.remindAt,
    dispatchedAt: new Date().toISOString(),
    status: 'scheduled_and_delivered'
  }
}];
